import re
import math
import csv
from datetime import datetime


def parse_amount(raw):
    if raw is None:
        return float("nan")
    s = raw.strip()
    if s == "":
        return float("nan")

    negative = False
    if "CR" in s.upper():
        negative = True
    if s.startswith("(") and s.endswith(")"):
        negative = True
    if "-" in s:
        negative = True

    # remove C1/C2 tokens first (so their digits don't leak into the number)
    cleaned = s.replace("C1", "").replace("C2", "")
    # keep only digits, comma, dot
    cleaned = re.sub(r"[^0-9,.]", "", cleaned)

    if cleaned == "":
        return float("nan")

    has_comma = "," in cleaned
    has_dot = "." in cleaned

    if has_comma and has_dot:
        last_comma = cleaned.rfind(",")
        last_dot = cleaned.rfind(".")
        if last_comma > last_dot:
            dec_sep, thou_sep = ",", "."
        else:
            dec_sep, thou_sep = ".", ","
        integer_part = cleaned.replace(thou_sep, "")
        integer_part = integer_part.replace(dec_sep, ".")
        number_str = integer_part
    elif has_comma or has_dot:
        sep = "," if has_comma else "."
        last_idx = cleaned.rfind(sep)
        digits_after = len(cleaned) - last_idx - 1
        if digits_after == 2:
            number_str = cleaned.replace(sep, ".")
        else:
            number_str = cleaned.replace(sep, "")
    else:
        number_str = cleaned

    try:
        value = float(number_str)
    except ValueError:
        return float("nan")

    if negative:
        value = -value
    return value


def parse_notes(raw):
    notes = raw or ""

    items = None
    m = re.search(r"items=(-?\d+)", notes)
    if m:
        items = int(m.group(1))

    adj_pct = 0.0
    m = re.search(r"adj=([+-]?\d+(?:\.\d+)?)%", notes)
    if m:
        adj_pct = float(m.group(1)) / 100.0

    fee = 0.0
    m = re.search(r"fee=([+-]?\d+(?:\.\d+)?)", notes)
    if m:
        fee = float(m.group(1))

    waive = bool(re.search(r"waive=true", notes, re.IGNORECASE))

    return items, adj_pct, fee, waive


def parse_event_time(raw):
    s = (raw or "").strip()
    if s == "":
        return None
    s2 = s.replace("Z", "+00:00") if s.endswith("Z") else s
    try:
        return datetime.fromisoformat(s2)
    except ValueError:
        return None


def median(values):
    v = sorted(values)
    n = len(v)
    if n == 0:
        return float("nan")
    mid = n // 2
    if n % 2 == 1:
        return v[mid]
    return (v[mid - 1] + v[mid]) / 2.0


def mad(values, med):
    return median([abs(x - med) for x in values])


def answer() -> list[str]:
    rows = []
    with open("/app/dataset/data.csv", newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        for idx, row in enumerate(reader):
            record_id = row["record_id"]
            event_time_raw = row["event_time"]
            region = row["region"]
            channel_raw = row["channel"]
            amount_str = row["amount_str"]
            notes_raw = row["notes"]

            event_time = parse_event_time(event_time_raw)
            channel = channel_raw.strip().lower()

            base_amount = parse_amount(amount_str)
            items, adj_pct, fee, waive = parse_notes(notes_raw)

            if math.isnan(base_amount):
                net = float("nan")
            else:
                net = base_amount * (1 + adj_pct) + fee
                if waive:
                    net = 0.0

            rows.append({
                "order": idx,
                "record_id": record_id,
                "event_time": event_time,
                "region": region,
                "channel": channel,
                "items": items,
                "net": net,
            })

    # dedup: keep one row per record_id -> latest event_time,
    # tie-break: prefer real (finite) net, then earlier file order
    best = {}
    for r in rows:
        rid = r["record_id"]
        if rid not in best:
            best[rid] = r
            continue
        cur = best[rid]

        cur_et = cur["event_time"]
        new_et = r["event_time"]

        def et_key(et):
            return (et is not None, et)

        if et_key(new_et) != et_key(cur_et):
            if et_key(new_et) > et_key(cur_et):
                best[rid] = r
            continue

        cur_real = not math.isnan(cur["net"])
        new_real = not math.isnan(r["net"])
        if new_real != cur_real:
            if new_real and not cur_real:
                best[rid] = r
            continue

        if r["order"] < cur["order"]:
            best[rid] = r

    dedup_rows = list(best.values())

    start = datetime.fromisoformat("2025-10-01T00:00:00+00:00")
    end = datetime.fromisoformat("2025-12-31T23:59:59+00:00")

    filtered = []
    for r in dedup_rows:
        if r["event_time"] is None:
            continue
        et = r["event_time"]
        if et.tzinfo is None:
            et_cmp = et
        else:
            et_cmp = et
        if et_cmp.tzinfo is not None:
            et_naive = et_cmp.astimezone(None).replace(tzinfo=None) if False else et_cmp
        # normalize comparisons using tz-aware start/end
        if not (start <= et <= end):
            continue
        if r["channel"] == "phone":
            continue
        if math.isnan(r["net"]) or math.isinf(r["net"]):
            continue
        filtered.append(r)

    groups = {}
    for r in filtered:
        month = r["event_time"].strftime("%Y-%m")
        key = (r["region"], month)
        groups.setdefault(key, []).append(r)

    for key, grp in groups.items():
        nets = [g["net"] for g in grp]
        med = median(nets)
        m = mad(nets, med)
        for g in grp:
            if m == 0:
                g["robust_z"] = 0.0
            else:
                g["robust_z"] = 0.6745 * (g["net"] - med) / m

    for r in filtered:
        items_eff = r["items"] if r["items"] is not None else 1
        items_eff = max(items_eff, 1)
        r["items_eff"] = items_eff
        r["anomaly_score"] = abs(r["robust_z"]) * math.log1p(items_eff)

    ranked = sorted(
        filtered,
        key=lambda r: (
            -r["anomaly_score"],
            -abs(r["robust_z"]),
            -(r["event_time"].timestamp()),
            r["record_id"],
        ),
    )

    top10 = [r["record_id"] for r in ranked[:10]]
    return top10


if __name__ == "__main__":
    import json
    result = answer()
    with open("/app/answer.json", "w") as f:
        json.dump(result, f, default=list)
    print(result)

